contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: attempts a lockInGuess with arbitrary amount and then checks balance effects
    function runTest(bytes32 h, uint256 sendAmount) public payable {
        // we need funds to send
        require(address(this).balance >= sendAmount);
        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // perform the state-changing call: lockInGuess with provided amount
        c.lockInGuess{value: sendAmount}(h);

        // balances after call
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // For the original contract P, lockInGuess requires msg.value == 1 ether,
        // so for any sendAmount != 1 ether the call would revert; thus when the call succeeds,
        // sendAmount must be exactly 1 ether and contract balance increases by exactly 1 ether.
        // The mutant M allows sendAmount >= 1 ether, so it can accept larger amounts, making
        // afterC - beforeC >= 1 ether. We assert the precise equality that holds only for P:
        assert(afterC - beforeC == 1 ether);
    }

    // allow the test contract to receive ether so tests can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // amount is the Ether sent to lockInGuess; hash is arbitrary bytes32
    function run(uint256 amount, bytes32 hash) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        // General rule: if the call succeeded, then the sent amount must equal exactly 1 ether
        assert(reverted || amount == 1 ether);
    }
    receive() external payable { }
}

