contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: drive c and assert the distinguishing property
    function runTest(bytes32 h1, uint256 sendAmount) public payable {
        // require the caller provided enough ether to forward to c
        require(msg.value == sendAmount);
        require(sendAmount == 1 ether);

        // precondition: caller currently has no active guess in c
        // we observe this by attempting to lock in a guess once; on P this should succeed
        c.lockInGuess{value: sendAmount}(h1);

        // After the first successful lockInGuess, the stored block for msg.sender must be nonzero.
        // We can observe that by calling the public getter for the mapping via the auto-generated
        // accessor: c.guesses(msg.sender) returns (uint, bytes32) because struct is public.
        (uint storedBlock, bytes32 storedHash) = c.guesses(msg.sender);

        // The distinguishing property (holds on P): storedBlock != 0
        // On mutant M (which flips the require to != 0), the first lockInGuess would revert,
        // so this assert would fail to hold universally (the mutant can't make storedBlock nonzero).
        assert(storedBlock != 0);
    }

    // allow contract to receive ether for forwarding
    receive() external payable {}
}

