contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, bytes32 hash) public payable {
        require(amount == 1 ether);
        // First call: should succeed for an address with no prior guess
        bool firstReverted;
        try c.lockInGuess{value: amount}(hash) { firstReverted = false; } catch { firstReverted = true; }

        // Second call: should revert because the caller now has a pending guess
        bool secondReverted;
        try c.lockInGuess{value: amount}(hash) { secondReverted = false; } catch { secondReverted = true; }

        // For the original contract P: first call does not revert, second call reverts.
        // The mutant M flips the initial guard and will cause the first call to revert instead.
        assert(firstReverted == false && secondReverted == true);
    }
    receive() external payable {}
}

