pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the actor and a candidate guess; the fuzzer will search values that expose the mutant
    function testFuzz_property(address actor, bytes32 guess) public {
        // keep actor sane
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // give actor some funds less than 1 ether to trigger the require(msg.value == 1 ether) revert
        // but we must still attempt the call with a value != 1 ether. Choose 0.5 ether via bound of available balance.
        uint256 sendAmount = 0.5 ether;
        vm.deal(actor, sendAmount);

        // ensure no previous guess is set for actor: call from actor should see default state
        // The contract has a public mapping auto-getter: guesses(address) returns (uint256 block, bytes32 guess)
        // but original C declared struct Guess and mapping guesses; compiler auto-generates guesses(address) getter.
        (uint256 beforeBlock, bytes32 beforeGuess) = c.guesses(actor);
        // should be zero-initialized initially
        assertTrue(beforeBlock == 0 && beforeGuess == bytes32(0));

        // actor calls lockInGuess but sends wrong amount -> reference should revert and leave state unchanged
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: sendAmount}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call (which for the reference will revert and thus not mutate state), the stored guess must remain zero.
        (, bytes32 afterGuess) = c.guesses(actor);

        // The universal property: for ALL inputs the reference leaves guesses[actor].guess == bytes32(0) when the call fails due to wrong value.
        // We observe via the public getter; this assertion will pass on the reference for all inputs, but fail on the mutant for some inputs
        // (those where the mutant wrote the guess before the require and the call reverted).
        assertTrue(afterGuess == bytes32(0));
    }
}

