pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the actor address and a guess value; the property concerns calls that revert due to wrong payment
    function testFuzz_property(address actor, bytes32 guess) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // pick an amount that is NOT 1 ether to trigger the payment revert branch
        uint256 wrongAmount = 0.5 ether;
        vm.assume(wrongAmount != 1 ether);

        // fund the actor so it can attempt the payable call
        vm.deal(actor, wrongAmount);

        // perform the call as actor; capture whether call succeeded
        bool ok;
        vm.startPrank(actor);
        try c.lockInGuess{value: wrongAmount}(guess) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The general rule: when the call supplies the wrong payment it must revert (ok == false)
        // and the contract must not have recorded the guess for actor (getter returns default bytes32(0)).
        // Some mutants that write state before the payment check will violate this by leaving a non-zero guess
        bytes32 stored = c.guesses(actor).guess;
        // single assertion: if the call reverted (as it should), stored guess must be zero
        // This reads only c's public getter and is a universal property the reference upholds.
        if (!ok) {
            assertTrue(stored == bytes32(0));
        } else {
            // If call unexpectedly succeeded (e.g., wrongAmount somehow equals 1 ether), then also assert stored matches provided guess
            assertTrue(stored == guess);
        }
    }
}

