pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz parameter: an address that will call lockInGuess
    function testFuzz_property(address caller) public {
        // admissible domain: non-zero address
        vm.assume(caller != address(0));

        // fund the caller so it can send 1 ether
        vm.deal(caller, 1 ether);

        // prepare a pseudorandom guess value derived from caller to keep inputs varied
        bytes32 guess = keccak256(abi.encodePacked(caller, block.number));

        // have the fuzzed caller call lockInGuess sending exactly 1 ether
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guess);

        // The universal property: after a successful lockInGuess the stored block for that caller is non-zero.
        // This is observable via the auto-generated public getter for the mapping's struct members.
        // We read the .block field through its getter (compiler auto-generates a getter for public mapping struct fields).
        // Note: If the mutant omitted setting the block, this assertion will fail for some caller inputs.
        (uint256 storedBlock, bytes32 storedGuess) = getGuess(c, caller);

        // exactly one assertion about c's public state
        assertTrue(storedBlock != 0);
    }

    // helper to read the mapping's struct (since direct tuple getter isn't available, we implement a small forwarder)
    // We cannot modify C, so we use a small external view call pattern: call a view that returns both fields by calling the auto-generated getters.
    // But as we cannot change C, we implement a low-overhead staticcall to read storage via the public getter function signature.
    // The mapping 'guesses' is of type mapping(address => Guess) and the compiler generates a getter
    // with signature: function guesses(address) external view returns (uint256, bytes32)
    function getGuess(C target, address who) internal returns (uint256 b, bytes32 g) {
        // Build calldata for guesses(address)
        bytes memory data = abi.encodeWithSignature("guesses(address)", who);
        (bool ok, bytes memory ret) = address(target).call(data);
        require(ok, "call to guesses getter failed");
        (b, g) = abi.decode(ret, (uint256, bytes32));
    }
}

