contract Attacker {
    C immutable target;
    bytes32 public observed;
    bytes32 private param;

    constructor(C _target, bytes32 _param) payable {
        target = _target;
        param = _param;
    }

    // Called by the fuzzing actor to initiate the sequence; this contract will call target.lockInGuess
    // and in its receive it will read the target's public getter to capture any mid-state.
