// Helper that performs calls from its own address so mappings use its address as key
contract Runner {
    address targetForward;

    function doLock(address caddr, bytes32 h) external payable {
        // forward call to C.lockInGuess
        (bool ok, ) = caddr.call{value: msg.value}(abi.encodeWithSignature("lockInGuess(bytes32)", h));
        require(ok, "lockIn failed");
    }

    function doSettle(address caddr) external {
        // call settle; this will attempt to send funds to this contract on success
        (bool ok, ) = caddr.call(abi.encodeWithSignature("settle()"));
        require(ok, "settle call failed");
    }

    function setTarget(address t) external {
        targetForward = t;
    }

    // receive will forward funds to target which is MaliciousReceiver that reverts
    receive() external payable {
        if (targetForward != address(0)) {
            // attempt to forward to target which may revert
            (bool ok, ) = targetForward.call{value: msg.value}("");
            // ignore ok here; if target reverts, this receive will revert as well
            require(ok, "forward failed");
        }
    }
}

contract MaliciousReceiver {
    receive() external payable {
        revert("I always revert");
    }
}

