        // Call settle as the same caller; catch whether it reverted
        bool ok;
        try c.settle{ gas: gasleft() }() {
            ok = true;
        } catch {
            ok = false;
        }

        // After settle completes (either success or revert), read the contract balance
        uint256 after = address(c).balance;

        // General rule to assert:
        // For the correct contract, whenever someone who locked a guess then calls settle
        // after the required block, the contract's balance never falls below 1 ether.
        // (The mutant may pay out 2 ether even when balance is only 1 ether, leaving balance < 1 ether.)
        assertTrue(after >= 1 ether);
    }
}

