contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed params: an address that will be the guesser (as actor) and a block offset to lock/wait
    function testFuzz_property(address actor, uint16 waitBlocks) public {
        // keep actor nonzero and waitBlocks moderately small so block.number + waitBlocks fits and test is meaningful
        vm.assume(actor != address(0));
        uint16 wb = waitBlocks % 10; // keep it small but fuzzer still explores

        // 1 ether initial funding done in setUp
        // prepare actor with 1 ether so they can lockInGuess
        vm.deal(actor, 1 ether);

        // craft a guess hash (any value, fuzz doesn't need it)
        bytes32 guess = keccak256(abi.encodePacked("x", actor, wb));

        // actor locks a guess paying 1 ether
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // advance blocks so settle's require(block.number > guesses[msg.sender].block) can be satisfied
        // guesses[msg].block is set to block.number + 1 in lockInGuess, so advance at least wb+2
        // but keep it small to not consume too many blocks
        uint256 advance = uint256(wb) + 2;
        for (uint256 i = 0; i < advance; i++) {
            vm.roll(block.number + 1);
        }

        // call settle as the actor; settle may transfer 2 ether if guess matches blockhash-derived answer
        // We don't control the answer; the property we assert is about contract balance never dropping below 1 ether
        // for the correct contract. The mutant can violate that for some inputs (fuzzer should find one).

        // capture balance before
        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        // call settle and ignore whether it reverts or not; settle in both versions does not revert on success
        try c.settle() {
            // no-op
        } catch {
            // no-op on revert
        }

        uint256 balAfter = address(c).balance;

        // General rule: for the correct contract, after calling settle (regardless of success/revert),
        // the contract's balance is never below 1 ether. The mutant can allow a 2 ether transfer when
        // only 1 ether was present, making balAfter < 1 ether for some inputs.
        assertTrue(balAfter >= 1 ether);
    }
}

