pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed params: an address that will act as the player, and a block offset to lock to a future block
    function testFuzz_property(address player, uint16 blocksAhead) public {
        // Keep domain wide but sensible: player should not be zero address
        vm.assume(player != address(0));
        // bound blocksAhead to a small range so block.number + blocksAhead won't overflow and is realistic
        uint16 ba = uint16(bound(uint256(blocksAhead), 1, 10));

        // fund the player so they can lock in 1 ether
        vm.deal(player, 1 ether);

        // player locks a guess for block.number + ba
        vm.prank(player);
        bytes32 hash = keccak256(abi.encodePacked(bytes32(uint256(1))));
        c.lockInGuess{value: 1 ether}(hash);

        // advance to the locked block + 1 so settle is callable (block.number > guesses[player].block)
        // lock was set to block.number + ba at lock time, so advance by ba+1
        vm.roll(block.number + uint256(ba) + 1);

        // Now call settle as the player and observe whether it reverts or not.
        // The correct contract will only attempt transfer when it has >=2 ether and thus will not revert
        // due to insufficient balance when transfer is attempted; the mutant can attempt transfer
        // despite insufficient balance and cause revert. We capture success/failure via try/catch.
        bool ok;
        vm.prank(player);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The single universal assertion: the reference contract never reverts in this scenario
        // because it only transfers when it has >= 2 ether; the mutant can revert for some inputs.
        assertTrue(ok);
    }
}
